        'Removido': ['Deleted', 'Eliminado', '已删除', '삭제됨'], 'Removida': ['Deleted', 'Eliminada', '已删除', '삭제됨'],
        'Retornada': ['Returned', 'Devuelta', '已退回', '반려됨'],
