        'Motivo do retorno': ['Reason for return', 'Motivo de la devolución', '退回原因', '반려 사유'],
        'Escreva o motivo.': ['Write the reason.', 'Escriba el motivo.', '请填写原因。', '사유를 입력하세요.'],
        'Para retornar, escreva o motivo do retorno.': ['To return, write the reason for the return.', 'Para devolver, escriba el motivo de la devolución.', '退回时请填写退回原因。', '반려하려면 반려 사유를 입력하세요.'],
